--   JOIN users u  ON u.id = m.user_id
--   JOIN groups g ON g.id = m.group_id
--   ORDER BY g.name, b.net_balance DESC;
--
-- Một mã QR trả cho nhiều hoá đơn (điểm khác biệt cốt lõi của PaySplit):
--   SELECT p.reference_code, p.amount, count(d.id) AS so_khoan_no,
--          string_agg(b.merchant_name, ' + ') AS cac_hoa_don
--   FROM payments p JOIN debts d ON d.payment_id = p.id
--   JOIN bills b ON b.id = d.bill_id
--   GROUP BY p.id HAVING count(d.id) > 1;
--
-- Bảng phân rã một hoá đơn tới từng món (truy vết mức item):
--   SELECT bi.name, gm_u.display_name, a.weight
--   FROM bill_items bi
--   JOIN bill_item_assignments a ON a.bill_item_id = bi.id
--   JOIN group_members gm ON gm.id = a.member_id
--   JOIN users gm_u ON gm_u.id = gm.user_id
--   WHERE bi.bill_id = '<bill_id>' ORDER BY bi.created_at;
